import React from 'react';

export const isHoverInChartBounds = (
  event: React.MouseEvent,
  chartRect?: DOMRect,
): boolean => {
  if (!chartRect) {
    return false;
  }

  const { clientX, clientY } = event;

  const chartStartPointX = chartRect.left;
  const chartEndPointX = chartRect.left + chartRect.width;
  const chartStartPointY = chartRect.top;
  const chartEndPointY = chartRect.top + chartRect.height;

  return !(
    clientX < chartStartPointX ||
    clientX > chartEndPointX ||
    clientY < chartStartPointY ||
    clientY > chartEndPointY
  );
};
